sp_widget.client_script:
api.controller = function($scope, $window, $http) {
  var c = this;

  c.sidebarCollapsed = false;
  c.chatbotOpen = false;

  c.toggleSidebar = function() {
    c.sidebarCollapsed = !c.sidebarCollapsed;
  };

  c.toggleChatbot = function() {
    c.chatbotOpen = !c.chatbotOpen;
  };

  c.goToPage = function(pageId) {
    $window.location.href = '?id=' + pageId;
  };

  c.selectedAcadYear = '2023 - 2027';
  c.filterBatch = 'ALL';
  c.filterBranch = 'ALL';
  c.filterStatus = 'ALL';
  c.filterPackage = 'ALL';
  c.filterCgpa = 'ALL';
  c.searchQuery = '';

  c.showNotifs = false;
  c.notifTab = 'ALL';

  c.activeModal = null;
  c.unplacedTab = 'ALL';

  c.showDrawer = false;
  c.drawerType = null;
  c.selectedStudent = null;
  c.selectedCompany = null;

  c.toggleNotifs = function() {
    c.showNotifs = !c.showNotifs;
  };

  c.clearNotifs = function() {
    c.showNotifs = false;
  };

  c.clearFilters = function() {
    c.selectedAcadYear = '2023 - 2027';
    c.filterBatch = 'ALL';
    c.filterBranch = 'ALL';
    c.filterStatus = 'ALL';
    c.filterPackage = 'ALL';
    c.filterCgpa = 'ALL';
    c.onFilterChange();
  };

  var masterStudents = [
    { name: 'Aarav Sharma', roll_number: '23CSE001', branch: 'CSE', cgpa: '8.4', batch: '2023-2027', status: 'Unplaced', applications: 3, interviews: 2, pkg: 0 },
    { name: 'Bhavna Patel', roll_number: '23ECE012', branch: 'ECE', cgpa: '7.8', batch: '2023-2027', status: 'Unplaced', applications: 2, interviews: 1, pkg: 0 },
    { name: 'Chirag Rao', roll_number: '23IT045', branch: 'IT', cgpa: '7.2', batch: '2023-2027', status: 'Unplaced', applications: 4, interviews: 3, pkg: 0 },
    { name: 'Divya Reddy', roll_number: '23CSE089', branch: 'CSE', cgpa: '6.9', batch: '2023-2027', status: 'Unplaced', applications: 1, interviews: 0, pkg: 0 },
    { name: 'Eshwar Kumar', roll_number: '23MECH004', branch: 'MECH', cgpa: '7.1', batch: '2023-2027', status: 'Unplaced', applications: 2, interviews: 1, pkg: 0 },
    { name: 'Farhan Ali', roll_number: '23CSE102', branch: 'CSE', cgpa: '8.1', batch: '2023-2027', status: 'Unplaced', applications: 5, interviews: 2, pkg: 0 },
    { name: 'Gauri Verma', roll_number: '23ECE056', branch: 'ECE', cgpa: '7.6', batch: '2023-2027', status: 'Unplaced', applications: 3, interviews: 1, pkg: 0 },
    { name: 'Harish Nair', roll_number: '23IT023', branch: 'IT', cgpa: '6.8', batch: '2023-2027', status: 'Unplaced', applications: 2, interviews: 0, pkg: 0 },
    { name: 'Isha Gupta', roll_number: '23CSE044', branch: 'CSE', cgpa: '8.6', batch: '2023-2027', status: 'Unplaced', applications: 4, interviews: 3, pkg: 0 },
    { name: 'Jayesh Singh', roll_number: '23MECH018', branch: 'MECH', cgpa: '7.4', batch: '2023-2027', status: 'Unplaced', applications: 1, interviews: 0, pkg: 0 },
    { name: 'Kavya Joshi', roll_number: '23ECE090', branch: 'ECE', cgpa: '7.9', batch: '2023-2027', status: 'Unplaced', applications: 3, interviews: 2, pkg: 0 },
    { name: 'Karan Shah', roll_number: '23CSE015', branch: 'CSE', cgpa: '9.1', batch: '2023-2027', status: 'Placed', applications: 2, interviews: 2, pkg: 12.5 },
    { name: 'Meera Das', roll_number: '23ECE004', branch: 'ECE', cgpa: '8.8', batch: '2023-2027', status: 'Placed', applications: 3, interviews: 2, pkg: 9.0 },
    { name: 'Nikhil Roy', roll_number: '23IT009', branch: 'IT', cgpa: '8.5', batch: '2023-2027', status: 'Placed', applications: 2, interviews: 1, pkg: 10.0 },
    { name: 'Ojaswini K', roll_number: '23CSE077', branch: 'CSE', cgpa: '7.7', batch: '2024-2028', status: 'In Progress', applications: 1, interviews: 1, pkg: 0 },
    { name: 'Pooja Hegde', roll_number: '23ECE044', branch: 'ECE', cgpa: '8.2', batch: '2024-2028', status: 'Unplaced', applications: 2, interviews: 1, pkg: 0 },
    { name: 'Rahul Varma', roll_number: '23IT088', branch: 'IT', cgpa: '7.0', batch: '2024-2028', status: 'Unplaced', applications: 1, interviews: 0, pkg: 0 },
    { name: 'Siddharth M', roll_number: '23MECH050', branch: 'MECH', cgpa: '6.7', batch: '2024-2028', status: 'Unplaced', applications: 1, interviews: 0, pkg: 0 }
  ];

  c.onFilterChange = function() {
    var filtered = masterStudents.filter(function(st) {
      if (c.filterBatch !== 'ALL' && st.batch !== c.filterBatch) return false;
      if (c.filterBranch !== 'ALL' && st.branch !== c.filterBranch) return false;
      if (c.filterStatus !== 'ALL' && st.status !== c.filterStatus) return false;

      var cg = parseFloat(st.cgpa);
      if (c.filterCgpa === '8.0+' && cg < 8.0) return false;
      if (c.filterCgpa === '7.5-8.0' && (cg < 7.5 || cg >= 8.0)) return false;
      if (c.filterCgpa === '7.0-7.5' && (cg < 7.0 || cg >= 7.5)) return false;
      if (c.filterCgpa === '<7.0' && cg >= 7.0) return false;

      if (c.filterPackage === '10+' && st.pkg < 10) return false;
      if (c.filterPackage === '6-10' && (st.pkg < 6 || st.pkg > 10)) return false;
      if (c.filterPackage === '<6' && st.pkg >= 6 && st.status === 'Placed') return false;

      return true;
    });

    var totalReg = filtered.length;
    var placedCount = filtered.filter(function(s) { return s.status === 'Placed'; }).length;
    var unplacedList = filtered.filter(function(s) { return s.status === 'Unplaced'; });
    var rate = totalReg > 0 ? ((placedCount / totalReg) * 100).toFixed(1) : 0;

    var highlyReady = filtered.filter(function(s) { return parseFloat(s.cgpa) >= 8.0; }).length;
    var readyCount = totalReg - highlyReady;
    var highlyReadyPct = totalReg > 0 ? Math.round((highlyReady / totalReg) * 100) : 0;
    var readyPct = 100 - highlyReadyPct;

    var monthNames = ['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May'];
    var monthlyData = [];
    var linePoints = [];
    var pathD = '';

    for (var i = 0; i < 12; i++) {
      var baseVal = (i + 1) * (totalReg > 0 ? (totalReg / 18) : 1);
      var offVal = Math.min(Math.round(baseVal * 0.8) + (i % 2), 15);
      var plcVal = Math.min(Math.round(baseVal * 0.6), offVal);
      var rateVal = offVal > 0 ? Math.round((plcVal / offVal) * 100) : 0;

      var x1 = 55 + (i * 45);
      var x2 = x1 + 15;
      var labelX = x1 + 7;

      var offersH = offVal * 8;
      var offersY = 165 - offersH;
      var placedH = plcVal * 8;
      var placedY = 165 - placedH;

      var cy = 165 - Math.round((rateVal / 100) * 120);

      monthlyData.push({
        month: monthNames[i],
        x1: x1, x2: x2, labelX: labelX,
        offersH: offersH, offersY: offersY,
        placedH: placedH, placedY: placedY
      });

      linePoints.push({ cx: x1 + 10, cy: cy });

      if (i === 0) {
        pathD += 'M ' + (x1 + 10) + ' ' + cy;
      } else {
        pathD += ' L ' + (x1 + 10) + ' ' + cy;
      }
    }

    c.stats = {
      totalCompanies: Math.min(3 + Math.floor(totalReg / 5), 6),
      activeDrives: Math.min(13, totalReg),
      registeredStudents: totalReg,
      offersMade: placedCount,
      placementRate: rate,
      unplacedCount: unplacedList.length,
      highlyReady: highlyReady,
      highlyReadyPct: highlyReadyPct,
      readyCount: readyCount,
      readyPct: readyPct,
      monthlyData: monthlyData,
      linePoints: linePoints,
      linePath: pathD,
      funnel: {
        registered: totalReg,
        participating: totalReg,
        applications: Math.round(totalReg * 1.4),
        interviews: Math.round(totalReg * 0.9)
      },
      topCompaniesList: [
        { name: 'CMP001', offers: Math.max(1, Math.floor(placedCount / 3)) },
        { name: 'CMP003', offers: Math.max(1, Math.floor(placedCount / 3)) },
        { name: 'CMP002', offers: Math.max(1, Math.floor(placedCount / 3)) }
      ],
      recentDrivesList: [
        { company: 'CMP001', role: 'APP DEVELOPER', date: '2026-09-30 00:00:00', cgpa: '8+ CGPA' },
        { company: 'CMP001', role: 'Software Developer', date: '2026-10-15 08:15:04', cgpa: '7.5+ CGPA' }
      ]
    };

    c.filteredUnplacedList = unplacedList;
  };

  c.onFilterChange();

  c.openModal = function(modalName) { c.activeModal = modalName; };
  c.closeModal = function() { c.activeModal = null; };

  c.openDrawer = function(type, dataObj) {
    c.drawerType = type;
    if (type === 'student') c.selectedStudent = dataObj;
    if (type === 'company') c.selectedCompany = dataObj;
    c.showDrawer = true;
  };

  c.closeDrawer = function() {
    c.showDrawer = false;
    c.drawerType = null;
  };

  c.exportCSV = function() {
    var csvContent = "data:text/csv;charset=utf-8,Student Name,Roll No,Branch,CGPA,Status\n";
    c.filteredUnplacedList.forEach(function(s) {
      csvContent += s.name + "," + s.roll_number + "," + s.branch + "," + s.cgpa + ",Unplaced\n";
    });
    var encodedUri = encodeURI(csvContent);
    var link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "unplaced_students_directory.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  c.drivesDetailedList = [
    { company: 'CMP001', role: 'APP DEVELOPER', date: '2026-09-30', stage: 'Online Assessment', cgpa: '8.0+', applicants: 18 },
    { company: 'CMP001', role: 'Software Developer', date: '2026-10-15', stage: 'Technical Round 1', cgpa: '7.5+', applicants: 14 },
    { company: 'CMP002', role: 'Data Analyst', date: '2026-10-20', stage: 'Resume Screening', cgpa: '7.0+', applicants: 12 },
    { company: 'CMP003', role: 'System Engineer', date: '2026-11-02', stage: 'Final Interview', cgpa: '7.5+', applicants: 8 }
  ];

  c.companiesDetailedList = [
    { name: 'CMP001', industry: 'Software / IT', offers: 1, package: '12.5 LPA' },
    { name: 'CMP002', industry: 'Analytics', offers: 1, package: '9.0 LPA' },
    { name: 'CMP003', industry: 'Core Tech', offers: 1, package: '10.0 LPA' }
  ];
};

sp_widget.css:
/* =========================================================
   CAMPUS360 PLACEMENT OUTCOMES
   NAVBAR + PURPLE SIDEBAR + ALIGNED FILTERS
   ========================================================= */


/* =========================================================
   FONT
   ========================================================= */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');


/* =========================================================
   VARIABLES
   ========================================================= */

:root{

  --navy:#100a27;
  --navy-dark:#0d0820;
  --navy-light:#1b143b;

  --purple:#7c3aed;
  --purple-dark:#6d28d9;
  --purple-soft:#f3e8ff;

  --blue:#2563eb;
  --green:#10b981;
  --orange:#f97316;
  --pink:#ec4899;
  --cyan:#0891b2;

  --bg:#f5f7fb;
  --white:#ffffff;

  --text:#10182b;
  --muted:#64748b;

  --line:#e2e8f0;

}


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body{

  width:100% !important;
  height:100% !important;

  min-width:100% !important;
  min-height:100% !important;

  margin:0 !important;
  padding:0 !important;

  overflow:hidden !important;

  background:
    var(--bg) !important;

}


*{
  box-sizing:border-box;
}


/* =========================================================
   HIDE NATIVE SERVICENOW NAVBAR
   ========================================================= */

body:has(.campus360-tpo-layout) #sp-header,
body:has(.campus360-tpo-layout) .sp-header,
body:has(.campus360-tpo-layout) .sp-navbar,
body:has(.campus360-tpo-layout) #sp-nav-bar,
body:has(.campus360-tpo-layout) .sp-nav-bar,
body:has(.campus360-tpo-layout) header#sp-header,
body:has(.campus360-tpo-layout) header.sp-header,
body:has(.campus360-tpo-layout) header.navbar,
body:has(.campus360-tpo-layout) nav.navbar,
body:has(.campus360-tpo-layout) .navbar.sp-navbar,
body:has(.campus360-tpo-layout) .navbar.navbar-default,
body:has(.campus360-tpo-layout) .navbar.navbar-inverse,
body:has(.campus360-tpo-layout) #responsiveNav{

  display:none !important;
  visibility:hidden !important;

  height:0 !important;
  min-height:0 !important;
  max-height:0 !important;

  width:0 !important;

  margin:0 !important;
  padding:0 !important;

  overflow:hidden !important;

  opacity:0 !important;

  pointer-events:none !important;

}


/* =========================================================
   SERVICE PORTAL OUTER SPACING
   ========================================================= */

body:has(.campus360-tpo-layout) #sp-page,
body:has(.campus360-tpo-layout) #sp-main,
body:has(.campus360-tpo-layout) .sp-page,
body:has(.campus360-tpo-layout) .sp-main,
body:has(.campus360-tpo-layout) .page-wrapper,
body:has(.campus360-tpo-layout) .main-content{

  width:100% !important;
  max-width:none !important;

  margin:0 !important;
  padding:0 !important;

}


/* =========================================================
   ROOT APPLICATION
   ========================================================= */

.campus360-tpo-layout{

  position:fixed !important;

  inset:0 !important;

  width:100vw !important;
  height:100vh !important;

  display:flex !important;

  overflow:hidden !important;

  background:
    var(--bg) !important;

  color:
    var(--text) !important;

  font-family:
    'Plus Jakarta Sans',
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Roboto,
    sans-serif !important;

  z-index:2147483647 !important;

}


/* =========================================================
   SIDEBAR
   DARK PURPLE LIKE THIRD IMAGE
   ========================================================= */

.tpo-sidebar{

  width:270px !important;
  min-width:270px !important;
  max-width:270px !important;

  height:100vh !important;

  flex:0 0 270px !important;

  display:flex !important;

  flex-direction:column !important;

  background:
    linear-gradient(
      180deg,
      #10092a 0%,
      #120c2e 50%,
      #0d0821 100%
    ) !important;

  border-right:
    1px solid #292143 !important;

  color:#ffffff !important;

  overflow-x:hidden !important;
  overflow-y:auto !important;

  scrollbar-width:none !important;

  z-index:2000 !important;

}


.tpo-sidebar::-webkit-scrollbar{

  width:0 !important;
  height:0 !important;

  display:none !important;

}


/* =========================================================
   SIDEBAR BRAND
   ========================================================= */

.sidebar-brand{

  min-height:90px !important;

  height:90px !important;

  padding:18px 19px !important;

  display:flex !important;

  align-items:center !important;

  gap:12px !important;

  border-bottom:
    1px solid rgba(255,255,255,.08) !important;

  flex-shrink:0 !important;

}


.brand-logo{

  width:50px !important;
  height:50px !important;

  min-width:50px !important;

  border-radius:14px !important;

  display:flex !important;

  align-items:center !important;
  justify-content:center !important;

  background:
    linear-gradient(
      135deg,
      #743be4,
      #8b4af3
    ) !important;

  color:#ffffff !important;

  font-size:24px !important;

  font-weight:900 !important;

  box-shadow:
    0 8px 22px rgba(124,58,237,.25) !important;

}


.brand-title{

  display:block !important;

  color:#ffffff !important;

  font-size:18px !important;

  font-weight:900 !important;

  letter-spacing:-.4px !important;

  line-height:1.1 !important;

}


.brand-sub{

  display:block !important;

  margin-top:4px !important;

  color:#c6b6ef !important;

  font-size:10px !important;

  font-weight:800 !important;

  letter-spacing:.8px !important;

}


/* =========================================================
   SIDEBAR USER CARD
   ========================================================= */

.sidebar-user{

  margin:16px 13px 10px !important;

  padding:12px 13px !important;

  min-height:73px !important;

  display:flex !important;

  align-items:center !important;

  gap:11px !important;

  background:
    linear-gradient(
      145deg,
      #1d1641,
      #241a4e
    ) !important;

  border:
    1px solid #392b63 !important;

  border-radius:15px !important;

  box-shadow:
    0 5px 15px rgba(0,0,0,.18) !important;

}


.user-avatar{

  width:44px !important;
  height:44px !important;

  min-width:44px !important;

  border-radius:50% !important;

  background:
    linear-gradient(
      135deg,
      #8c50ed,
      #7337dd
    ) !important;

  color:#ffffff !important;

  display:flex !important;

  align-items:center !important;
  justify-content:center !important;

  font-size:13px !important;

  font-weight:900 !important;

}


.user-info{

  min-width:0 !important;

  display:flex !important;

  flex-direction:column !important;

}


.user-name{

  color:#ffffff !important;

  font-size:13px !important;

  font-weight:900 !important;

}


.user-role{

  margin-top:3px !important;

  color:#c4b4ed !important;

  font-size:9px !important;

  font-weight:700 !important;

  white-space:nowrap !important;

  overflow:hidden !important;

  text-overflow:ellipsis !important;

}


/* =========================================================
   SIDEBAR NAV
   ========================================================= */

.sidebar-nav{

  flex:1 1 auto !important;

  min-height:0 !important;

  padding:
    3px 11px 18px !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  scrollbar-width:none !important;

}


.sidebar-nav::-webkit-scrollbar{

  width:0 !important;
  height:0 !important;

  display:none !important;

}


.nav-section-title{

  padding:
    15px 14px 7px !important;

  color:#8e87a4 !important;

  font-size:9px !important;

  font-weight:900 !important;

  letter-spacing:1.3px !important;

}


.nav-item{

  width:100% !important;

  min-height:42px !important;

  padding:
    0 13px !important;

  margin-bottom:3px !important;

  display:flex !important;

  align-items:center !important;

  gap:11px !important;

  border-radius:10px !important;

  color:#ded9ed !important;

  background:transparent !important;

  text-decoration:none !important;

  font-size:12px !important;

  font-weight:700 !important;

  cursor:pointer !important;

  transition:
    background .15s ease,
    color .15s ease,
    transform .15s ease !important;

}


.nav-item:hover{

  background:
    rgba(255,255,255,.07) !important;

  color:#ffffff !important;

  text-decoration:none !important;

  transform:
    translateX(1px) !important;

}


.nav-item.active{

  background:
    linear-gradient(
      90deg,
      #7b3aed 0%,
      #8b44ef 100%
    ) !important;

  color:#ffffff !important;

  box-shadow:
    0 8px 20px
    rgba(124,58,237,.25) !important;

}


.nav-icon{

  width:20px !important;

  min-width:20px !important;

  text-align:center !important;

  font-size:15px !important;

  color:#bdb5d0 !important;

}


.nav-item.active .nav-icon,
.nav-item:hover .nav-icon{

  color:#ffffff !important;

}


.nav-label{

  flex:1 !important;

  min-width:0 !important;

  white-space:nowrap !important;

  overflow:hidden !important;

  text-overflow:ellipsis !important;

}


.nav-badge{

  min-width:23px !important;

  height:23px !important;

  padding:0 6px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border-radius:50% !important;

  background:
    #342758 !important;

  color:#cdbef1 !important;

  font-size:9px !important;

  font-weight:900 !important;

}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.sidebar-footer{

  flex-shrink:0 !important;

  padding:
    15px !important;

  border-top:
    1px solid rgba(255,255,255,.06) !important;

  color:#817b95 !important;

  font-size:8px !important;

  text-align:center !important;

}


/* =========================================================
   SIDEBAR COLLAPSED
   ========================================================= */

.campus360-tpo-layout.sidebar-collapsed
.tpo-sidebar{

  width:0 !important;
  min-width:0 !important;
  max-width:0 !important;

  flex-basis:0 !important;

  transform:
    translateX(-100%) !important;

  opacity:0 !important;

  pointer-events:none !important;

  overflow:hidden !important;

}


.campus360-tpo-layout.sidebar-collapsed
.tpo-right-container{

  width:100vw !important;

  flex:1 1 100% !important;

}


/* =========================================================
   RIGHT SIDE
   ========================================================= */

.tpo-right-container{

  min-width:0 !important;

  min-height:0 !important;

  height:100vh !important;

  flex:1 1 auto !important;

  display:flex !important;

  flex-direction:column !important;

  overflow:hidden !important;

  background:
    var(--bg) !important;

}


/* =========================================================
   CUSTOM TOP NAVBAR
   MATCH FIRST IMAGE
   ========================================================= */

.tpo-top-navbar{

  width:100% !important;

  height:68px !important;

  min-height:68px !important;
  max-height:68px !important;

  flex:0 0 68px !important;

  padding:
    0 20px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  background:#ffffff !important;

  border-bottom:
    1px solid #e1e5ec !important;

  box-shadow:
    0 1px 3px rgba(15,23,42,.035) !important;

  z-index:3000 !important;

}


/* =========================================================
   TOP LEFT
   ========================================================= */

.top-nav-left{

  display:flex !important;

  align-items:center !important;

  gap:14px !important;

  min-width:0 !important;

}


.btn-toggle-sidebar{

  width:43px !important;

  height:43px !important;

  min-width:43px !important;

  padding:0 !important;

  margin:0 !important;

  border:
    1px solid #dce1e9 !important;

  border-radius:11px !important;

  background:#ffffff !important;

  color:#4e5b70 !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:19px !important;

  cursor:pointer !important;

  outline:none !important;

}


.btn-toggle-sidebar:hover{

